import { describe, it } from 'node:test';
import assert from 'node:assert';
import { load, CORE_SCHEMA } from 'js-yaml';

describe('proof', () => {
  it('explicit !!int octal without sign resolves', () => {
    assert.strictEqual(load('!!int "0o10"', { schema: CORE_SCHEMA }), 10);
  });
});

